import type { APIGatewayProxyEvent, APIGatewayProxyResult } from "aws-lambda";
import { TransactWriteCommand } from "@aws-sdk/lib-dynamodb";
import type { TransactionCanceledException } from "@aws-sdk/client-dynamodb";
import Ajv from "ajv";
import { actorKey, ddb, movieKey, type Role, tableName, toRole } from "../shared/db";
import { isResponse, parseJsonObject, response } from "../shared/http";
import { logRequest } from "../shared/request-logger";
import roleSchema from "../shared/role.schema.json";

// Validates a POST payload against the Role schema generated by `npm run schema`.
const ajv = new Ajv();
const isValidRolePayload = ajv.compile<Role>(roleSchema);

export const handler = async (
  event: APIGatewayProxyEvent
): Promise<APIGatewayProxyResult> => {
  logRequest(event);

  const body = parseJsonObject(event);
  if (isResponse(body)) return body;

  // Reject a body that doesn't match the Role type (missing, extra or wrong-type fields).
  if (!isValidRolePayload(body)) {
    return response(400, {
      message: "Incorrect type. Must match the Role schema",
      schema: roleSchema,
    });
  }
  const role = toRole(body);

  // One transaction: the movie must exist, the actor must exist, and the role must be new.
  // If any check fails, nothing is written.
  try {
    await ddb.send(
      new TransactWriteCommand({
        TransactItems: [
          {
            ConditionCheck: {
              TableName: tableName,
              Key: { PK: movieKey(role.movieId), SK: movieKey(role.movieId) },
              ConditionExpression: "attribute_exists(PK)",
            },
          },
          {
            ConditionCheck: {
              TableName: tableName,
              Key: { PK: actorKey(role.actorId), SK: actorKey(role.actorId) },
              ConditionExpression: "attribute_exists(PK)",
            },
          },
          {
            Put: {
              TableName: tableName,
              Item: { PK: movieKey(role.movieId), SK: actorKey(role.actorId), ...role },
              ConditionExpression: "attribute_not_exists(PK)",
            },
          },
        ],
      })
    );
    return response(201, { message: "Role added", data: role });
  } catch (err) {
    // CancellationReasons are in the same order as TransactItems,
    // so they show which check failed -> 404 (movie/actor) or 409 (duplicate).
    if ((err as Error).name === "TransactionCanceledException") {
      const [movieCheck, actorCheck, rolePut] =
        (err as TransactionCanceledException).CancellationReasons ?? [];
      if (movieCheck?.Code === "ConditionalCheckFailed") {
        return response(404, { message: `Movie ${role.movieId} not found` });
      }
      if (actorCheck?.Code === "ConditionalCheckFailed") {
        return response(404, { message: `Actor ${role.actorId} not found` });
      }
      if (rolePut?.Code === "ConditionalCheckFailed") {
        return response(409, {
          message: `Actor ${role.actorId} already has a role in movie ${role.movieId}`,
        });
      }
    }
    console.error("DynamoDB error:", err);
    return response(500, { message: "Internal server error" });
  }
};
